//! Colony yield model — deterministic economic output calculations
//!
//! # Colony Yield Model v2
//!
//! Each turn a colony produces the following resources, derived from its
//! population, installed buildings, orbital structures, colony stability, and
//! the class of the planet it occupies:
//!
//! * **Industry** — the effective production base:
//!   `population + FabricationYard × 2 + stability_modifier`
//!   where `stability_modifier = (stability − 100) / 10` (0 at neutral 100).
//!
//! * **Credits** — `industry × prod_pct / 100`
//!
//! * **Science** — `industry × research_pct / 100 + ScienceNexus × population
//!   + planet_science_bonus`
//!
//! * **Food** — `population + planet_food_bonus + AquacultureBay × population`
//!
//! * **Food consumed** — `population` (always equals base population)

//! Game state types and domain models

use rand_chacha::ChaCha8Rng;
#[cfg(feature = "serde")]
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet, VecDeque};

/// Unique identifier for a star system
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub struct StarId(pub u64);

/// Unique identifier for a sector
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub struct SectorId(pub u64);

/// Unique identifier for an empire
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]

//! Events emitted by the game engine

use crate::state::{
    BuildItem, ColonyAutomation, ColonyId, ColonyRole, ColonyUnrestState, CustomDesignId,
    DiplomaticCommunicationType, EmpireId, EspionageMission, FleetFormation, FleetId, FleetOrder,
    FleetRole, HullId, IntelLevel, IntelSource, PlanetAnomaly, PlanetSpecial, SectorDirective,
    SectorId, StarId, StrategicResource, TechId, TreatyType, UnrestCause, VictoryPath,
};
#[cfg(feature = "serde")]
use serde::{Deserialize, Serialize};

/// Events generated by the game engine in response to commands
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub enum Event {
    /// Turn has advanced
    TurnAdvanced { new_turn: u32 },
    /// Colony focus was set
    ColonyFocusSet { colony: ColonyId },
    /// Fleet has moved

    }

    /// Return true when this lane links the two provided stars (order agnostic).
    pub fn connects(&self, from: StarId, to: StarId) -> bool {
        Self::new(from, to) == Some(*self)
    }

    pub fn a(&self) -> StarId {
        self.a
    }

    pub fn b(&self) -> StarId {
        self.b
    }

    pub fn endpoints(&self) -> (StarId, StarId) {
        (self.a, self.b)
    }
}

    pub fn label(self) -> &'static str {
        match self {
            EspionageMission::GatherIntelligence => "Gather Intelligence",
            EspionageMission::SabotageProduction => "Sabotage Production",
            EspionageMission::StealResearch => "Steal Research",
        }
    }
}

/// Persisted intelligence state for one foreign empire.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub struct EmpireIntel {
    #[cfg_attr(feature = "serde", serde(default))]
    pub level: IntelLevel,
    #[cfg_attr(feature = "serde", serde(default))]
    pub points: u16,
    #[cfg_attr(feature = "serde", serde(default))]
    pub last_gather_turn: Option<u32>,
}

